export const CLASS_SKILLS={
 kiem:{slash:{name:'Kiếm khí liên hoàn',mp:18,cd:5,range:7,multi:1.8,step:.24,shape:'cone',color:0xffd47a},nova:{name:'Thiên kiếm chấn',mp:30,cd:9,range:8,multi:1.3,step:.22,stun:1.2,shape:'circle',color:0xf6bb4b},mend:{name:'Kiếm tâm hộ thể',mp:25,cd:13,heal:.23,shield:.6,color:0xe9d997}},
 phap:{slash:{name:'Hỏa cầu liên tinh',mp:22,cd:5.5,range:15,multi:2,step:.28,shape:'single',color:0xff7049},nova:{name:'Băng liên trận',mp:34,cd:10,range:12,multi:1.15,step:.24,stun:1.8,shape:'circle',color:0x7cdbff},mend:{name:'Linh tuyền hồi phục',mp:20,cd:12,heal:.3,color:0x8edbdb}},
 thuong:{slash:{name:'Xuyên tâm thương',mp:16,cd:4.5,range:11,multi:1.9,step:.25,shape:'line',color:0xa9e8c2},nova:{name:'Bão thương phá trận',mp:28,cd:8,range:9,multi:1.45,step:.23,stun:.8,shape:'circle',color:0x85d4aa},mend:{name:'Chiến ý bất khuất',mp:24,cd:14,heal:.2,shield:1.2,color:0xb8df85}}
};
export function classSkill(s,k){const base=CLASS_SKILLS[s.class]?.[k];if(!base)return null;const rank=Math.max(1,s.upgrades[k]||1),path=s.companions?.skillPaths[k]||'balanced';return {...base,rank,cooldown:base.cd*(path==='swift'?.75:1),multiplier:((base.multi||1)+(rank-1)*(base.step||0))*(path==='power'?1.2:1),heal:((base.heal||.25)+(rank-1)*.025)*(path==='power'?1.2:1),stun:(base.stun||0)+(rank-1)*.12,shield:(base.shield||0)+(base.shield?(rank-1)*.08:0)};}
export function skillTargets(s,skill,enemies,selected,facing=0){let list=enemies.filter(e=>Math.hypot(e.x-s.x,e.z-s.z)<=skill.range);const aim=list.find(e=>e.id===selected)||list.sort((a,b)=>Math.hypot(a.x-s.x,a.z-s.z)-Math.hypot(b.x-s.x,b.z-s.z))[0];if(skill.shape==='single')return aim?[aim]:[];if(skill.shape==='circle')return list;const angle=aim?Math.atan2(aim.x-s.x,aim.z-s.z):facing;return list.filter(e=>{const dx=e.x-s.x,dz=e.z-s.z,forward=dx*Math.sin(angle)+dz*Math.cos(angle),side=Math.abs(dx*Math.cos(angle)-dz*Math.sin(angle));return forward>=0&&(skill.shape==='line'?side<=1.8:side<=forward*.85+1);});}
